# ===== v5：doSearch 并发令牌（快速连搜时只有最后一次有权写结果/关 isSearching） =====
python3 << 'PYEOF'
import sys

path = "avbox/app/src/main/java/com/github/tvbox/osc/ui/activity/LxMusicSearchActivity.kt"
with open(path, encoding="utf-8") as f:
    src = f.read()

MARK = "// [31v5-token]"
if MARK in src:
    print("跳过（31v5-token 已应用）")
    sys.exit(0)

def rep1(old, new, tag):
    global src
    if src.count(old) != 1:
        print(f"错误：31v5 锚点计数异常 [{tag}]: {src.count(old)}", file=sys.stderr)
        sys.exit(1)
    src = src.replace(old, new, 1)

if "import kotlinx.coroutines.delay" not in src:
    rep1("import kotlinx.coroutines.launch",
         "import kotlinx.coroutines.launch\nimport kotlinx.coroutines.delay", "delay-import")

rep1("    var isSearching by remember { mutableStateOf(false) }",
     "    var isSearching by remember { mutableStateOf(false) }\n    var searchSeq by remember { mutableStateOf(0) } " + MARK, "seq-decl")

rep1("        isSearching = true\n        errorMsg = null\n        scope.launch {",
     "        isSearching = true\n        errorMsg = null\n        val mySeq = ++searchSeq " + MARK + "\n        scope.launch {", "seq-take")

rep1("                val both = LxMusicSearchApi.searchBoth(keyword.trim())",
     "                val both = LxMusicSearchApi.searchBoth(keyword.trim())\n                if (mySeq != searchSeq) return@launch " + MARK, "seq-guard")

rep1('                errorMsg = "搜索失败: ${e.message}"',
     '                if (mySeq == searchSeq) errorMsg = "搜索失败: ${e.message}"', "seq-catch")

rep1("            } finally {\n                isSearching = false\n            }",
     "            } finally {\n                if (mySeq == searchSeq) isSearching = false " + MARK + "\n            }", "seq-finally")

with open(path, "w", encoding="utf-8") as f:
    f.write(src)
print("31v5：doSearch 并发令牌已应用")
PYEOF
# ===== v5 结束 =====
